const normalizeAnalyticsPath = (input: string) => {
  const pathname = String(input || '/').split('?')[0].slice(0, 180);
  return pathname
    .replace(/[0-9a-f]{8}-[0-9a-f-]{27,}/gi, ':id')
    .replace(/\/newsletter\/issues\/[^/]+/g, '/newsletter/issues/:date')
    .replace(/\/newsletter\/archive\/[^/]+/g, '/newsletter/archive/:month');
};

const featureForPath = (pathName: string) => {
  const pathValue = normalizeAnalyticsPath(pathName);
  if (pathValue.includes('newsletter')) return 'Newsletter';
  if (pathValue.includes('quiz')) return 'Quizzes';
  if (pathValue.includes('worksheet')) return 'Worksheets';
  if (pathValue.includes('social-stor')) return 'Social stories';
  if (pathValue.includes('activit')) return 'Activities';
  if (pathValue.includes('reward') || pathValue.includes('behavior-bonus')) return 'Rewards';
  if (pathValue.includes('report')) return 'Reports';
  if (pathValue.includes('data-management')) return 'Data management';
  if (pathValue.includes('profile') || pathValue.includes('/kids')) return 'Profiles';
  if (pathValue.includes('assistant')) return 'Parent assistant';
  if (pathValue === '/' || pathValue.includes('about') || pathValue.includes('features')) return 'Public information';
  return 'Other';
};

const workflowStepForRequest = (routeTemplate: string, method: string) => {
  const route = routeTemplate.toLowerCase();
  const verb = method.toUpperCase();
  if (route.includes('generate-art') || route.includes('generate-image') || route.includes('/upload')) return route.includes('/upload') ? 'Upload' : 'Create illustration';
  if (route.includes('generate')) return 'Generate';
  if (route.includes('preview')) return 'Preview';
  if (route.includes('quiz-results') || route.includes('quiz-attempt')) return verb === 'GET' ? 'Review result' : 'Submit attempt';
  if (route.includes('assign')) return 'Assign';
  if (route.includes('verif') || route.includes('complete')) return 'Review completion';
  if (route.includes('behavior-bonus')) return 'Award bonus';
  if (verb === 'DELETE') return 'Delete';
  if (verb === 'GET') return 'Open or load';
  if (verb === 'POST') return 'Create or submit';
  return 'Update';
};

const reasonCodeForResponse = (req: any, statusCode: number) => {
  if (statusCode < 400) return 'none';
  const hint = String(req.insightsErrorHint || '').toLowerCase();
  if (statusCode === 401) return 'session_or_sign_in_required';
  if (statusCode === 403) return 'permission_denied';
  if (statusCode === 404) return 'record_not_found';
  if (statusCode === 409) return 'conflict_or_already_exists';
  if (statusCode === 413 || /file.*(large|size)|mb or smaller/.test(hint)) return 'file_too_large';
  if (statusCode === 429 || /(allowance|daily limit|limit reached|too many)/.test(hint)) return 'allowance_reached';
  if (statusCode >= 500) return /generat|gemini|illustration|image/.test(`${req.path} ${hint}`) ? 'generation_or_ai_service_failed' : 'service_unavailable';
  if (/(required|missing|complete all|choose|enter a|confirm)/.test(hint)) return 'required_information_missing';
  if (/(invalid|valid |unsupported|must be|between)/.test(hint)) return 'invalid_information_or_format';
  if (/(expired|no longer available)/.test(hint)) return 'expired_or_unavailable';
  if (/(already|submitted|completed|duplicate)/.test(hint)) return 'already_completed_or_exists';
  return 'request_not_accepted';
};

const recordParentAction = (req: any, statusCode: number) => {
  if (!supabaseServiceKey || req.user?.role !== 'parent' || req.path.startsWith('/api/admin/')) return;
  const routeTemplate = normalizeAnalyticsPath(req.path);
  const action = req.method === 'GET' ? 'viewed' : req.method === 'POST' ? 'created' : req.method === 'DELETE' ? 'deleted' : 'updated';
  const outcome = statusCode >= 500 ? 'server_error' : statusCode >= 400 ? 'client_error' : 'success';
  const durationMs = Math.min(120000, Math.max(0, Date.now() - Number(req.insightsStartedAt || Date.now())));
  void getAdminSupabaseClient().from('parent_activity_events').insert({
    user_id: req.user.id,
    feature: featureForPath(routeTemplate),
    action,
    route_template: routeTemplate,
    workflow_step: workflowStepForRequest(routeTemplate, req.method),
    outcome,
    response_status: statusCode,
    reason_code: reasonCodeForResponse(req, statusCode),
    duration_ms: durationMs,
  }).then(({ error }) => { if (error && !isProduction) console.warn('Parent analytics event skipped:', error.message); });
};

// Helper Functions
type SafeSmtpError = {
  code: string;
  command?: string;
  responseCode?: number;
};

const getSafeSmtpError = (error: any): SafeSmtpError => ({
  code: String(error?.code || 'SMTP_ERROR').slice(0, 80),
  ...(error?.command ? { command: String(error.command).slice(0, 40) } : {}),
  ...(Number.isFinite(error?.responseCode) ? { responseCode: Number(error.responseCode) } : {}),
});

const getMissingSmtpVariables = () => {
  const requiredVariables = ['SMTP_HOST', 'SMTP_PORT', 'SMTP_USER', 'SMTP_PASS', 'SMTP_FROM'];
  return requiredVariables.filter((name) => !cleanEnvVar(name));
};

const getTransporter = async () => {
  const smtpUser = cleanEnvVar('SMTP_USER');
  const smtpPass = cleanEnvVar('SMTP_PASS');
  const smtpHost = cleanEnvVar('SMTP_HOST') || 'smtp.ethereal.email';
  const smtpPort = parseInt(cleanEnvVar('SMTP_PORT') || '587');

  const transporter = nodemailer.createTransport({
    host: smtpHost,
    port: smtpPort,
    secure: smtpPort === 465,
    auth: {
      user: smtpUser,
      pass: smtpPass,
    },
    connectionTimeout: 10_000,
    greetingTimeout: 10_000,
    socketTimeout: 20_000,
  });

  // If no credentials are provided, try to create a test account for development
  if (!smtpUser || !smtpPass) {
    if (process.env.NODE_ENV === 'production') {
      console.warn('Skipping email: SMTP credentials are incomplete in production.', {
        missingVariables: getMissingSmtpVariables(),
      });
      return null;
    }
    console.log('No SMTP_USER provided. Creating Ethereal test account...');
    const testAccount = await nodemailer.createTestAccount();
    (transporter.options as any).host = 'smtp.ethereal.email';
    (transporter.options as any).port = 587;
    (transporter.options as any).secure = false;
    (transporter.options as any).auth = {
      user: testAccount.user,
      pass: testAccount.pass,
    };
    console.log('Using Ethereal test account for emails:', testAccount.user);
  }

  return transporter;
};

const contactRequestWindows = new Map<string, { count: number; startedAt: number }>();
const CONTACT_RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000;
const CONTACT_RATE_LIMIT_MAX_REQUESTS = 5;

const getContactRequestKey = (req: express.Request) => {
  const forwardedFor = String(req.headers['x-forwarded-for'] || '').split(',')[0]?.trim();
  return forwardedFor || req.ip || 'unknown';
};

const isContactRequestRateLimited = (req: express.Request) => {
  const now = Date.now();
  const key = getContactRequestKey(req);
  const current = contactRequestWindows.get(key);
  if (!current || now - current.startedAt >= CONTACT_RATE_LIMIT_WINDOW_MS) {
    contactRequestWindows.set(key, { count: 1, startedAt: now });
    return false;
  }
  current.count += 1;
  return current.count > CONTACT_RATE_LIMIT_MAX_REQUESTS;
};

const isRecentlyIntroducedFeature = (introducedOn: string, now = new Date()) => {
  const introducedAt = new Date(`${introducedOn}T00:00:00Z`).getTime();
  const age = now.getTime() - introducedAt;
  return age >= 0 && age < 30 * 24 * 60 * 60 * 1000;
};

const buildWelcomeFeatureContent = (appUrl: string, now = new Date()) => {
  const features = productFeatureRegistry.filter(feature => feature.surfaces.includes('home')).map(currentRegistryFeature);
  return {
    text: features
      .map(feature => `- ${isRecentlyIntroducedFeature(feature.introducedOn, now) ? 'NEW: ' : ''}${feature.title}: ${feature.summary} Learn more: ${appUrl}/features/${feature.id}`)
      .join('\n'),
    html: features
      .map(feature => {
        const newLabel = isRecentlyIntroducedFeature(feature.introducedOn, now)
          ? '<span style="display:inline-block;margin-left:8px;padding:2px 7px;border-radius:999px;background:#dcfce7;color:#166534;font-size:11px;font-weight:700;text-transform:uppercase;">New</span>'
          : '';
        return `<li style="margin:0 0 12px;"><strong style="color:#1e293b;">${escapeEmailHtml(feature.title)}</strong>${newLabel}<br><span>${escapeEmailHtml(feature.summary)}</span> <a href="${appUrl}/features/${encodeURIComponent(feature.id)}" style="color:#2563eb;text-decoration:none;font-weight:600;">Read more</a></li>`;
      })
      .join(''),
  };
};

