const conciseNewsletterText = (value: string, sentenceLimit = 2) => {
  const sentences = String(value || '').match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [];
  return sentences.slice(0, sentenceLimit).map(sentence => sentence.trim()).join(' ');
};
const addVisualStepsUtility = (value: string, note: string, include: boolean) => include
  ? `${conciseNewsletterText(value, 1)} ${note}`
  : conciseNewsletterText(value);
const isoDate = (date: Date) => date.toISOString().slice(0, 10);
const formatNewsletterDate = (value: string | Date) => {
  const date = value instanceof Date ? value : new Date(`${value}T12:00:00Z`);
  return new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' })
    .format(date).replace(/^(\d{2}) ([A-Za-z]{3}) /, (_match, day, month) => `${Number.parseInt(day, 10)} ${month}, `);
};
const normalizeNewsletterDateText = (value: string) => {
  const monthIndex: Record<string, number> = { jan: 0, january: 0, feb: 1, february: 1, mar: 2, march: 2, apr: 3, april: 3, may: 4, jun: 5, june: 5, jul: 6, july: 6, aug: 7, august: 7, sep: 8, sept: 8, september: 8, oct: 9, october: 9, nov: 10, november: 10, dec: 11, december: 11 };
  const fromParts = (year: number, month: number, day: number) => formatNewsletterDate(new Date(Date.UTC(year, month, day)));
  return value
    .replace(/\b(\d{4})-(\d{2})-(\d{2})\b/g, (_match, year, month, day) => fromParts(Number(year), Number(month) - 1, Number(day)))
    .replace(/\b(January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\s+(\d{1,2}),\s+(\d{4})\b/gi, (_match, month, day, year) => fromParts(Number(year), monthIndex[String(month).toLowerCase()], Number(day)))
    .replace(/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/g, (_match, month, day, year) => fromParts(Number(year), Number(month) - 1, Number(day)));
};
const normalizeUpcomingNewsletterTitle = (value: string) => {
  const normalized = normalizeNewsletterDateText(value).trim();
  return /^Visual Steps Weekly\s*[—–-]\s*\d{1,2}\s+[A-Za-z]{3},?\s+\d{4}$/i.test(normalized)
    ? 'Visual Steps Weekly'
    : normalized;
};
const validNewsletterTimezone = (value: unknown) => {
  const timezone = String(value || '').trim();
  try { new Intl.DateTimeFormat('en-US', { timeZone: timezone }).format(); return timezone; }
  catch { return ''; }
};
const getNewsletterLocalParts = (date: Date, timezone: string) => {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
    timeZone: timezone, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hourCycle: 'h23',
  }).formatToParts(date).filter(part => part.type !== 'literal').map(part => [part.type, part.value]));
  const weekday = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(parts.weekday);
  return { weekday, hour: Number(parts.hour), date: `${parts.year}-${parts.month}-${parts.day}` };
};
const getPreviousNewsletterPeriod = (now = new Date(), deliveryWeekday = 1, deliveryTimezone = 'America/New_York') => {
  const localDate = getNewsletterLocalParts(now, deliveryTimezone).date;
  const issueDay = new Date(`${localDate}T12:00:00.000Z`);
  const daysSinceDelivery = (issueDay.getUTCDay() - deliveryWeekday + 7) % 7;
  issueDay.setUTCDate(issueDay.getUTCDate() - daysSinceDelivery);
  const periodStart = new Date(issueDay);
  periodStart.setUTCDate(periodStart.getUTCDate() - 7);
  const periodEnd = new Date(issueDay);
  periodEnd.setUTCDate(periodEnd.getUTCDate() - 1);
  return { issueDate: isoDate(issueDay), periodStart: isoDate(periodStart), periodEnd: isoDate(periodEnd) };
};

const getNewsletterDeliverySettings = async () => {
  const { data } = await getAdminSupabaseClient().from('newsletter_settings').select('delivery_weekday,delivery_hour,delivery_timezone').eq('id', true).maybeSingle();
  return {
    deliveryWeekday: Number.isInteger(data?.delivery_weekday) ? Number(data.delivery_weekday) : 1,
    deliveryHour: Number.isInteger(data?.delivery_hour) ? Number(data.delivery_hour) : 0,
    deliveryTimezone: validNewsletterTimezone(data?.delivery_timezone) || 'America/New_York',
  };
};

const getNextNewsletterDate = (now: Date, deliveryWeekday: number, deliveryHour: number, deliveryTimezone: string) => {
  const candidate = new Date(now);
  candidate.setUTCMinutes(0, 0, 0);
  candidate.setUTCHours(candidate.getUTCHours() + 1);
  for (let index = 0; index < 24 * 8; index += 1) {
    const local = getNewsletterLocalParts(candidate, deliveryTimezone);
    if (local.weekday === deliveryWeekday && local.hour === deliveryHour) return candidate;
    candidate.setUTCHours(candidate.getUTCHours() + 1);
  }
  throw new Error('Unable to calculate the next newsletter delivery');
};

const buildWeeklyNewsletter = async (now = new Date(), published = false, deliveryWeekday = 1, deliveryTimezone = 'America/New_York') => {
  if (!supabaseServiceKey) throw new Error('SUPABASE_SERVICE_ROLE_KEY is required for newsletter publishing');
  const admin = getAdminSupabaseClient();
  const period = getPreviousNewsletterPeriod(now, deliveryWeekday, deliveryTimezone);
  const { data: pastIssues, error: pastIssueError } = await admin.from('newsletters')
    .select('parent_tips,recommended_resources,suggested_books_resources,popular_features,membership_details,feature_details')
    .not('published_at', 'is', null).neq('issue_date', period.issueDate)
    .order('issue_date', { ascending: false }).limit(52);
  if (pastIssueError) throw pastIssueError;
  const previouslyUsedTips = new Set((pastIssues || []).flatMap(issue => Array.isArray(issue.parent_tips) ? issue.parent_tips : []));
  const previouslyUsedActivities = new Set((pastIssues || []).flatMap(issue => Array.isArray(issue.recommended_resources) ? issue.recommended_resources.map((item: any) => item.title) : []));
  const previouslyUsedBooks = new Set((pastIssues || []).flatMap(issue => Array.isArray(issue.suggested_books_resources) ? issue.suggested_books_resources.map((item: any) => item.title) : []));
  const previouslyUsedPopularFeatures = new Set((pastIssues || []).flatMap(issue => Array.isArray(issue.popular_features) ? issue.popular_features.map((item: any) => item.title) : []));
  const previouslyUsedVisualStepsSuggestions = new Set((pastIssues || []).flatMap(issue => Array.isArray(issue.feature_details) ? issue.feature_details : []));
  const newlyIntroducedFeatures = productFeatureRegistry.filter(feature =>
    feature.introducedOn >= period.periodStart && feature.introducedOn <= period.periodEnd
  );
  const newlyIntroducedIds = new Set(newlyIntroducedFeatures.map(feature => feature.id));
  const featureChanges = [
    ...newlyIntroducedFeatures.map(feature => ({
      id: feature.id, title: feature.title, summary: feature.summary, details: feature.details,
      familyImpact: getNewsletterFeatureImpact(feature), help: feature.help,
      changeType: 'new' as const, changedOn: feature.introducedOn, screenshot: feature.screenshot,
    })),
    ...productFeatureRegistry.flatMap(feature => ('updates' in feature ? feature.updates : [])
      .filter(update => !newlyIntroducedIds.has(feature.id) && update.updatedOn >= period.periodStart && update.updatedOn <= period.periodEnd)
      .map(update => ({
        id: feature.id, title: update.title, summary: update.summary, details: update.details,
        familyImpact: update.familyImpact, help: update.help || feature.help,
        changeType: 'updated' as const, changedOn: update.updatedOn, screenshot: update.screenshot || feature.screenshot,
      }))),
  ].sort((a, b) => a.changedOn.localeCompare(b.changedOn));
  const { data: testimonials, error: testimonialError } = await admin
    .from('parent_testimonials').select('display_name,quote,feature_title,approved_at')
    .gte('approved_at', `${period.periodStart}T00:00:00.000Z`)
    .lt('approved_at', `${period.issueDate}T00:00:00.000Z`).order('approved_at', { ascending: true });
  if (testimonialError) throw testimonialError;
  const { data: communityPosts, error: communityError } = await admin.from('newsletter_community_submissions')
    .select('contribution_type,title,content,display_name,source_url,reviewed_at')
    .eq('status', 'approved').eq('consent_to_publish', true)
    .gte('reviewed_at', `${period.periodStart}T00:00:00.000Z`).lt('reviewed_at', `${period.issueDate}T00:00:00.000Z`)
    .order('reviewed_at', { ascending: true });
  if (communityError) throw communityError;
  const popularitySources = [
    ['Visual activities', 'activities'], ['Quizzes', 'quizzes'], ['Worksheets', 'worksheets'], ['Social stories', 'social_stories'], ['Positive behavior bonuses', 'behavior_bonus_awards'],
  ] as const;
  const popularityExplanations: Record<string, string> = {
    'Visual activities': 'Families use visual activities to make self-care, movement, learning, work preparation, household routines, and community goals clearer. Steps can be adapted for an autistic person’s age, autonomy, communication, abilities, and preferred support so caregivers participate without taking over.',
    'Quizzes': 'Personalized quizzes can check understanding and guide the next learning experience when the topic, language, presentation, and goals are age-appropriate. Caregivers can use results to offer another explanation or accessible practice rather than focusing only on scores.',
    'Worksheets': 'Printable worksheets can support intellectual, communication, practical, or interest-based goals away from the screen. Families should select or adapt them for the person’s age, motor access, learning style, and real-life goals rather than assuming worksheets suit everyone.',
    'Social stories': 'Social narratives can prepare autistic people of different ages for routines, changes, health care, education, work, travel, and community experiences. Respectful language and the person’s own perspective help caregivers plan support together instead of using the story only to demand compliance.',
    'Positive behavior bonuses': 'Behavior bonuses help parents and caregivers recognize specific effort, self-advocacy, regulation, cooperation, or growth without giving free rewards on request. Recognition should remain age-respectful and connected to what the autistic person values.',
  };
  const popularFeatures = (await Promise.all(popularitySources.map(async ([title, table]) => {
    const { count } = await admin.from(table).select('*', { count: 'exact', head: true });
    return { title, usageCount: count || 0, explanation: popularityExplanations[title] };
  }))).sort((a, b) => b.usageCount - a.usageCount).filter(item => !previouslyUsedPopularFeatures.has(item.title)).slice(0, 3).map(({ title, explanation }) => ({ title, explanation: conciseNewsletterText(explanation) }));
  const tipOffset = Math.floor(now.getTime() / (7 * 24 * 60 * 60 * 1000)) % newsletterTips.length;
  const unusedTips = newsletterTips.filter(tip => !previouslyUsedTips.has(tip));
  const tips = unusedTips.length ? [0, 1, 2, 3, 4].map((_, index) => addVisualStepsUtility(
    unusedTips[(tipOffset + index) % unusedTips.length],
    index === 0
      ? 'If a visible reminder would help, add the routine or support as a short Visual Steps activity and invite the child or adult to review it with you.'
      : 'Use the completed, repeated, on-hold, or ended activity outcome in Visual Steps to record the next planning decision without judging the person by one difficult day.',
    index === 0 || index === 3,
  )).filter((tip, index, list) => list.indexOf(tip) === index) : [];
  const unusedActivities = newsletterActivitiesAndGames.filter(item => !previouslyUsedActivities.has(item.title)).slice(0, 5).map((item, index) => ({
    ...item,
    description: addVisualStepsUtility(
      item.description,
      index === 0
        ? 'You can place the idea in Visual Steps with a clear time, picture, and only the steps that make participation easier.'
        : 'If the idea may be useful again, save it as a recurring or reusable Visual Steps activity and adjust the support after reviewing how it went.',
      index === 0 || index === 3,
    ),
  }));
  const unusedBooks = newsletterBooksAndResources.filter(item => !previouslyUsedBooks.has(item.title)).slice(0, 5).map((item, index) => ({
    ...item,
    description: addVisualStepsUtility(
      item.description,
      'When the resource inspires one relevant next step, add that specific idea to Visual Steps rather than turning the entire resource into another assignment.',
      index === 1,
    ),
  }));
  const visualStepsSuggestions = newsletterVisualStepsSuggestions.filter(item => !previouslyUsedVisualStepsSuggestions.has(item)).slice(0, 5);
  const issue = {
    issue_date: period.issueDate,
    period_start: period.periodStart,
    period_end: period.periodEnd,
    title: 'Visual Steps Weekly',
    introduction: `A practical summary of Visual Steps updates from ${formatNewsletterDate(period.periodStart)} through ${formatNewsletterDate(period.periodEnd)}, with suggestions centered on ${newsletterEditorialFocus}.`,
    new_features: featureChanges.map(({ screenshot: _screenshot, ...change }) => ({
      ...change,
      compact: true,
      description: `${conciseNewsletterText(change.summary, 1)} ${conciseNewsletterText(change.familyImpact, 1)}`.trim(),
    })),
    feature_details: visualStepsSuggestions,
    feature_previews: [],
    parent_testimonials: [...(testimonials || []).map(item => ({ displayName: item.display_name, quote: item.quote, featureTitle: item.feature_title, editorialContext: newsletterTestimonialContext })), ...(communityPosts || []).filter(item => item.contribution_type === 'testimonial').map(item => ({ displayName: item.display_name, quote: item.content, featureTitle: item.title, editorialContext: newsletterTestimonialContext }))],
    community_posts: (communityPosts || []).filter(item => !['testimonial', 'advertisement'].includes(item.contribution_type)).map(item => ({ type: item.contribution_type, title: item.title, content: item.content, displayName: item.display_name, sourceUrl: item.source_url, editorialContext: newsletterCommunityContext })),
    popular_features: popularFeatures,
    recommended_resources: unusedActivities,
    suggested_books_resources: unusedBooks,
    advertisements: (communityPosts || []).filter(item => item.contribution_type === 'advertisement').map(item => ({ advertiser: item.display_name, title: item.title, description: item.content, destinationUrl: item.source_url, disclosure: 'Advertisement reviewed for relevance to the Visual Steps mission. Appearance is not a medical endorsement.' })),
    membership_details: currentMembershipDetails,
    footer_links: {
      mainPage: cleanEnvVar('APP_URL') || PRODUCTION_APP_URL,
      pricing: `${cleanEnvVar('APP_URL') || PRODUCTION_APP_URL}/pricing`,
      subscribe: `${cleanEnvVar('APP_URL') || PRODUCTION_APP_URL}/newsletter/subscribe`,
      facebook: cleanEnvVar('FACEBOOK_URL'),
      instagram: cleanEnvVar('INSTAGRAM_URL'),
    },
    parent_tips: tips,
    section_titles: newsletterSectionTitles,
    section_visibility: newsletterSectionVisibility,
    published_at: published ? new Date().toISOString() : null,
  };
  return issue;
};

const createWeeklyNewsletter = async (now = new Date()) => {
  const admin = getAdminSupabaseClient();
  const settings = await getNewsletterDeliverySettings();
  const generated = await buildWeeklyNewsletter(now, true, settings.deliveryWeekday, settings.deliveryTimezone);
  const { data: savedDraft } = await admin.from('newsletters').select('title,introduction,section_titles,section_visibility,published_at').eq('issue_date', generated.issue_date).maybeSingle();
  const issue = savedDraft && !savedDraft.published_at ? {
    ...generated,
    title: normalizeUpcomingNewsletterTitle(savedDraft.title),
    introduction: normalizeNewsletterDateText(savedDraft.introduction),
    section_titles: upcomingNewsletterSectionTitles(savedDraft.section_titles || {}),
    section_visibility: { ...newsletterSectionVisibility, ...(savedDraft.section_visibility || {}), feature_previews: false },
  } : generated;
  const { data, error } = await admin.from('newsletters').upsert(issue, { onConflict: 'issue_date' }).select('*').single();
  if (error) throw error;
  return data;
};

const baseNewsletterSectionHtml = (title: string, items: string[], columns = 1, bulleted = false, numbered = false) => items.length ? `
  <h2 style="color:#173b52;margin:28px 0 10px">${escapeEmailHtml(title)}</h2>
  <div style="background:#f0f9ff;border:1px solid #bae6fd;border-radius:14px;padding:16px 20px;text-align:justify;text-justify:inter-word">${bulleted || numbered || title === newsletterSectionTitles.new_features ? `<${numbered || title === newsletterSectionTitles.new_features ? 'ol' : 'ul'} style="padding-left:22px;line-height:1.7;margin:0">${items.map(item => `<li style="margin-bottom:12px;text-align:justify;text-justify:inter-word">${item}</li>`).join('')}</${numbered || title === newsletterSectionTitles.new_features ? 'ol' : 'ul'}>` : `<div style="display:grid;grid-template-columns:1fr;gap:14px;line-height:1.7">${items.map(item => `<div style="text-align:justify;text-justify:inter-word;${columns === 2 ? 'background:#ffffff;border:1px solid #dbeafe;border-radius:10px;padding:12px;' : ''}">${item}</div>`).join('')}</div>`}</div>` : '';

const wrapNewsletterPreviewText = (value: unknown, maxCharacters: number, maxLines: number) => {
  const words = String(value || '').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  const lines: string[] = [];
  let line = '';
  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;
    if (candidate.length <= maxCharacters) line = candidate;
    else {
      if (line) lines.push(line);
      line = word;
      if (lines.length >= maxLines) break;
    }
  }
  if (line && lines.length < maxLines) lines.push(line);
  if (words.join(' ').length > lines.join(' ').length && lines.length) lines[lines.length - 1] = `${lines[lines.length - 1].replace(/[.,;:]?$/, '')}…`;
  return lines;
};

const getNewsletterPreviewContents = (issue: any) => {
  const visible = (key: string) => issue.section_visibility?.[key] !== false;
  const title = (key: string, fallback: string) => issue.section_titles?.[key] || fallback;
  const entries: string[] = [];
  const add = (key: string, fallback: string, items: unknown[]) => { if (visible(key) && items?.length) entries.push(title(key, fallback)); };
  add('feature_previews', 'Feature Previews', issue.feature_previews || []);
  if (visible('community_posts')) {
    const community = issue.community_posts || [];
    [['story', 'Parent Stories'], ['news', 'Community News'], ['information', 'Helpful Information'], ['tip', 'Community Tips and Tricks']].forEach(([type, fallback]) => {
      const items = community.filter((item: any) => item.type === type);
      if (items.length) entries.push(title(`community_${type}`, fallback));
    });
  }
  add('parent_testimonials', 'Parent Testimonials', issue.parent_testimonials || []);
  add('feature_details', 'Practical Ways to Use Visual Steps', issue.feature_details || []);
  add('popular_features', 'Most Popular Features', issue.popular_features || []);
  add('recommended_resources', 'Suggested Activities, Games, Puzzles and Other Ideas', issue.recommended_resources || []);
  add('suggested_books_resources', 'Suggested Books, Places and Resources', issue.suggested_books_resources || []);
  add('advertisements', 'Mission-Aligned Advertisements', issue.advertisements || []);
  add('parent_tips', 'Tips and Tricks for Parents', issue.parent_tips || []);
  add('new_features', "What's New in Visual Steps", issue.new_features || []);
  add('membership_details', 'Current Visual Steps Membership Details', issue.membership_details || []);
  return entries.slice(0, 11);
};

const createNewsletterEmailPreview = async (issue: any) => {
  const titleLines = wrapNewsletterPreviewText(issue.title, 25, 3);
  const introductionLines = wrapNewsletterPreviewText(issue.introduction, 48, 7);
  const contents = getNewsletterPreviewContents(issue);
  const lineText = (lines: string[], x: number, startY: number, size: number, lineHeight: number, weight = 400, color = '#425b56') => lines.map((line, index) => `<text x="${x}" y="${startY + index * lineHeight}" font-size="${size}" font-weight="${weight}" fill="${color}">${escapeEmailHtml(line)}</text>`).join('');
  const contentsText = contents.map((entry, index) => `<text x="675" y="${166 + index * 38}" font-size="18" font-weight="700" fill="#243b3a">${index + 1}. ${escapeEmailHtml(entry)}</text>`).join('');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="675" viewBox="0 0 1200 675">
    <rect width="1200" height="675" rx="26" fill="#dfcfaa"/>
    <rect x="18" y="18" width="570" height="639" rx="18" fill="#fffdf8"/>
    <rect x="612" y="18" width="570" height="639" rx="18" fill="#fffdf8"/>
    <rect x="588" y="18" width="24" height="639" fill="#e5e7eb" opacity=".7"/>
    <text x="58" y="78" font-family="Arial, sans-serif" font-size="18" font-weight="800" letter-spacing="2" fill="#176b87">VISUAL STEPS WEEKLY</text>
    ${lineText(titleLines, 58, 142, 42, 49, 800, '#172b27')}
    ${lineText(introductionLines, 58, 320, 19, 31)}
    <line x1="58" y1="580" x2="548" y2="580" stroke="#cfe4df" stroke-width="2"/>
    <text x="58" y="616" font-family="Arial, sans-serif" font-size="17" font-weight="700" fill="#176b87">Open the complete issue in your browser</text>
    <text x="652" y="86" font-family="Arial, sans-serif" font-size="38" font-weight="800" fill="#172b27">Contents</text>
    <text x="652" y="120" font-family="Arial, sans-serif" font-size="17" fill="#64748b">A quick look at this week’s issue</text>
    ${contentsText}
    <text x="1138" y="625" text-anchor="end" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#176b87">READ ONLINE →</text>
  </svg>`;
  return sharp(Buffer.from(svg)).png({ compressionLevel: 9 }).toBuffer();
};

const sendNewsletterIssue = async (issue: any, appOrigin: string) => {
  const admin = getAdminSupabaseClient();
  const { data: subscribers, error } = await admin.from('newsletter_subscribers')
    .select('id,email,unsubscribe_token_hash,last_sent_issue_date')
    .eq('status', 'active').or(`last_sent_issue_date.is.null,last_sent_issue_date.lt.${issue.issue_date}`).limit(100);
  if (error) throw error;
  const transporter = await getTransporter();
  if (!transporter) throw new Error('SMTP is not configured');
  const from = cleanEnvVar('SMTP_FROM') || cleanEnvVar('SMTP_USER');
  const issueUrl = `${appOrigin}/newsletter/issues/${encodeURIComponent(issue.issue_date)}`;
  const emailPreview = await createNewsletterEmailPreview(issue);
  let delivered = 0;
  for (const subscriber of subscribers || []) {
    // Store a newly rotated unsubscribe token because hashes cannot be reversed.
    const unsubscribeToken = randomBytes(32).toString('hex');
    const unsubscribeHash = hashNewsletterToken(unsubscribeToken);
    const unsubscribeUrl = `${appOrigin}/api/newsletter/unsubscribe?token=${encodeURIComponent(unsubscribeToken)}`;
    const archiveUrl = `${appOrigin}/newsletter`;
    let deferredMeaningfulUseSection = '';
    const newsletterSectionHtml = (title: string, items: string[], columns = 1, bulleted = false, numbered = false) => {
      const rendered = baseNewsletterSectionHtml(title, items, columns, bulleted, numbered);
      if (issue.section_visibility?.concise_editorial !== true) return rendered;
      if (title === (issue.section_titles?.feature_details || newsletterSectionTitles.feature_details)) {
        deferredMeaningfulUseSection = rendered;
        return '';
      }
      if (title === (issue.section_titles?.parent_testimonials || newsletterSectionTitles.parent_testimonials)) {
        const meaningfulUse = deferredMeaningfulUseSection;
        deferredMeaningfulUseSection = '';
        return `${rendered}${meaningfulUse}`;
      }
      if (title === (issue.section_titles?.popular_features || newsletterSectionTitles.popular_features) && deferredMeaningfulUseSection) {
        const meaningfulUse = deferredMeaningfulUseSection;
        deferredMeaningfulUseSection = '';
        return `${meaningfulUse}${rendered}`;
      }
      return rendered;
    };
    const featureItems = (issue.new_features || []).map((item: any) => item.compact
      ? `<strong>${escapeEmailHtml(item.title)}</strong><br>${escapeEmailHtml(item.description || [item.bullets?.find((bullet: any) => bullet.label === 'What changed')?.text, item.bullets?.find((bullet: any) => bullet.label === 'How it can help')?.text].filter(Boolean).join(' '))}${item.id ? `<br><a href="${appOrigin}/features/${encodeURIComponent(item.id)}${item.changeType === 'updated' && item.changedOn ? `?update=${encodeURIComponent(item.changedOn)}` : ''}">Read more</a>` : ''}`
      : `<span style="display:inline-block;background:#dbeafe;color:#1e40af;border-radius:999px;padding:3px 9px;font-size:11px;font-weight:bold;text-transform:uppercase">${item.changeType === 'updated' ? 'Feature update' : 'New feature'}</span><br><strong>${escapeEmailHtml(item.title)}</strong><br>${escapeEmailHtml(item.summary)}<br>${escapeEmailHtml(item.details)}<br><strong>How this supports growth:</strong> ${escapeEmailHtml(item.familyImpact)}<br><em>Where to find it:</em> ${escapeEmailHtml(item.help)}${item.id ? `<br><a href="${appOrigin}/features/${encodeURIComponent(item.id)}${item.changeType === 'updated' && item.changedOn ? `?update=${encodeURIComponent(item.changedOn)}` : ''}">Read more</a>` : ''}`);
    const visualStepsSuggestionItems = (issue.feature_details || []).map((item: string) => escapeEmailHtml(item));
    const testimonialItems = (issue.parent_testimonials || []).map((item: any) => `<strong>By ${escapeEmailHtml(item.displayName)}</strong>${renderNewsletterMarkdownForEmail(item.quote)}${item.editorialContext ? `<br><em>${escapeEmailHtml(item.editorialContext)}</em>` : ''}`);
    const tipItems = (issue.parent_tips || []).map((item: string) => escapeEmailHtml(item));
    const previewItems = (issue.feature_previews || []).map((item: any) => `<strong>${escapeEmailHtml(item.title)}</strong><br>${escapeEmailHtml(item.caption)}${item.familyImpact ? `<br><strong>Why it matters:</strong> ${escapeEmailHtml(item.familyImpact)}` : ''}${item.id ? `<br><a href="${appOrigin}/features/${encodeURIComponent(item.id)}">Read more</a>` : ''}`);
    const communityItemsFor = (type: string) => (issue.community_posts || []).filter((item: any) => item.type === type).map((item: any) => `<article><strong style="font-size:20px;color:#172033">${escapeEmailHtml(item.title)}</strong><br><span style="font-size:14px;font-weight:bold;color:#475569">By ${escapeEmailHtml(item.displayName)}</span><div style="margin-top:14px;text-align:left;line-height:1.7">${renderNewsletterMarkdownForEmail(item.content)}</div>${item.sourceUrl ? `<br><a href="${escapeEmailHtml(item.sourceUrl)}">Source</a>` : ''}${item.editorialContext ? `<br><em>${escapeEmailHtml(item.editorialContext)}</em>` : ''}</article>`);
    const communitySectionsHtml = [
      ['story', 'Parent Stories'], ['news', 'Community News'], ['information', 'Helpful Information'], ['tip', 'Community Tips and Tricks'],
    ].map(([type, fallbackTitle]) => newsletterSectionHtml(issue.section_titles?.[`community_${type}`] || fallbackTitle, communityItemsFor(type))).join('');
    const popularItems = (issue.popular_features || []).map((item: any) => `<strong>${escapeEmailHtml(item.title)}</strong> — ${escapeEmailHtml(item.explanation)}`);
    const resourceItems = (issue.recommended_resources || []).map((item: any) => `<strong>${escapeEmailHtml(item.title)}</strong> (${escapeEmailHtml(item.type)}) — ${escapeEmailHtml(item.description)}`);
    const bookResourceItems = (issue.suggested_books_resources || []).map((item: any) => `<strong>${escapeEmailHtml(item.title)}</strong> (${escapeEmailHtml(item.type)})${item.creator ? ` by ${escapeEmailHtml(item.creator)}` : ''} — ${escapeEmailHtml(item.description)}${item.url ? `<br><a href="${escapeEmailHtml(item.url)}">Visit resource</a>` : ''}`);
    const advertisementItems = (issue.advertisements || []).map((item: any) => `<strong>Advertisement: ${escapeEmailHtml(item.title)}</strong><br>${escapeEmailHtml(item.description)}<br><em>From ${escapeEmailHtml(item.advertiser)}. ${escapeEmailHtml(item.disclosure)}</em>${item.destinationUrl ? `<br><a href="${escapeEmailHtml(item.destinationUrl)}">Visit advertiser</a>` : ''}`);
    const membershipItems = (issue.membership_details || []).map((item: any) => `<strong>${escapeEmailHtml(item.name)}: ${escapeEmailHtml(item.price)}</strong> — ${escapeEmailHtml(item.status)}. ${escapeEmailHtml(item.details)}`);
    const footerLinks = [
      ['Visual Steps Home', appOrigin],
      ['Pricing', `${appOrigin}/pricing`],
      ['Subscribe Newsletter', `${appOrigin}/newsletter/subscribe`],
      ['Facebook', issue.footer_links?.facebook], ['Instagram', issue.footer_links?.instagram],
    ].filter((item): item is [string, string] => Boolean(item[1]));
    const footerLinksHtml = footerLinks.map(([label, url]) => `<a href="${escapeEmailHtml(url)}">${escapeEmailHtml(label)}</a>`).join(' &nbsp;|&nbsp; ');
    try {
      await transporter.sendMail({
        from, to: subscriber.email, subject: issue.title,
        text: `${issue.introduction}\n\nRead this issue: ${issueUrl}\n\nUnsubscribe: ${unsubscribeUrl}`,
        html: `<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#334155;line-height:1.6;background:#fffdf7;padding:24px"><a href="${escapeEmailHtml(issueUrl)}" style="display:block;margin:0 0 22px;text-decoration:none"><img src="cid:visual-steps-newsletter-preview" width="680" alt="Open the first two pages of ${escapeEmailHtml(issue.title)}" style="display:block;width:100%;height:auto;border:0;border-radius:14px"/></a><div style="background:linear-gradient(135deg,#dbeafe,#d1fae5);border-radius:18px;padding:24px"><h1 style="color:#176b87;margin-top:0">${escapeEmailHtml(issue.title)}</h1><p style="text-align:justify;text-justify:inter-word">${escapeEmailHtml(issue.introduction)}</p></div>${issue.section_visibility?.feature_previews === false ? '' : newsletterSectionHtml(issue.section_titles?.feature_previews || newsletterSectionTitles.feature_previews, previewItems)}${issue.section_visibility?.concise_editorial === true || issue.section_visibility?.new_features === false ? '' : newsletterSectionHtml(issue.section_titles?.new_features || 'New and Updated Feature Details', featureItems, 2)}${issue.section_visibility?.concise_editorial === true && issue.section_visibility?.feature_details !== false ? newsletterSectionHtml(issue.section_titles?.feature_details || newsletterSectionTitles.feature_details, visualStepsSuggestionItems, 1, true) : ''}${issue.section_visibility?.community_posts === false ? '' : communitySectionsHtml}${issue.section_visibility?.parent_testimonials === false ? '' : newsletterSectionHtml(issue.section_titles?.parent_testimonials || newsletterSectionTitles.parent_testimonials, testimonialItems)}${issue.section_visibility?.popular_features === false ? '' : newsletterSectionHtml(issue.section_titles?.popular_features || newsletterSectionTitles.popular_features, popularItems)}${issue.section_visibility?.recommended_resources === false ? '' : newsletterSectionHtml(issue.section_titles?.recommended_resources || newsletterSectionTitles.recommended_resources, resourceItems)}${issue.section_visibility?.suggested_books_resources === false ? '' : newsletterSectionHtml(issue.section_titles?.suggested_books_resources || newsletterSectionTitles.suggested_books_resources, bookResourceItems, 2)}${issue.section_visibility?.advertisements === false ? '' : newsletterSectionHtml(issue.section_titles?.advertisements || newsletterSectionTitles.advertisements, advertisementItems, 2)}${issue.section_visibility?.parent_tips === false ? '' : newsletterSectionHtml(issue.section_titles?.parent_tips || newsletterSectionTitles.parent_tips, tipItems, 1, true)}${issue.section_visibility?.concise_editorial === true && issue.section_visibility?.new_features !== false ? newsletterSectionHtml(issue.section_titles?.new_features || newsletterSectionTitles.new_features, featureItems, 2) : ''}${issue.section_visibility?.membership_details === false ? '' : newsletterSectionHtml(issue.section_titles?.membership_details || newsletterSectionTitles.membership_details, membershipItems)}<p style="margin-top:32px">${footerLinksHtml}</p><p><a href="${archiveUrl}">Read the illustrated newsletter archive</a></p><p style="font-size:12px;color:#64748b">You received this because you confirmed a Visual Steps newsletter subscription. <a href="${unsubscribeUrl}">Unsubscribe with one click</a>.</p></div>`,
        attachments: [{ filename: `visual-steps-weekly-${issue.issue_date}.png`, content: emailPreview, cid: 'visual-steps-newsletter-preview', contentType: 'image/png' }],
      });
      await admin.from('newsletter_subscribers').update({ last_sent_issue_date: issue.issue_date, unsubscribe_token_hash: unsubscribeHash, updated_at: new Date().toISOString() }).eq('id', subscriber.id);
      delivered += 1;
    } catch (sendError) {
      console.error('Newsletter delivery failed:', getSafeSmtpError(sendError));
    }
  }
  return { delivered, pending: (subscribers || []).length - delivered };
};

