app.get(['/api/cron/weekly-newsletter', '/api/cron/weekly-newsletter/:utcHour'], async (req, res) => {
  const cronSecret = cleanEnvVar('CRON_SECRET');
  if (!cronSecret || req.get('authorization') !== `Bearer ${cronSecret}`) return res.status(401).json({ error: 'Unauthorized' });
  try {
    // Reuse the existing protected hourly schedule for once-daily analytics
    // maintenance. A missing migration must not interrupt newsletter delivery.
    if (String(req.params.utcHour || '') === '7') {
      await getAdminSupabaseClient().rpc('rollup_and_prune_admin_analytics');
    }
    const now = new Date();
    const settings = await getNewsletterDeliverySettings();
    const local = getNewsletterLocalParts(now, settings.deliveryTimezone);
    if (local.weekday !== settings.deliveryWeekday || local.hour < settings.deliveryHour) return res.json({ skipped: true, reason: 'Not the configured newsletter delivery time' });
    const period = getPreviousNewsletterPeriod(now, settings.deliveryWeekday, settings.deliveryTimezone);
    const { data: publishedIssue, error: publishedIssueError } = await getAdminSupabaseClient().from('newsletters')
      .select('*').eq('issue_date', period.issueDate).not('published_at', 'is', null).maybeSingle();
    if (publishedIssueError) throw publishedIssueError;
    // Later cron runs on the selected day act as safe retries. Reuse the saved
    // issue and let subscriber last-sent dates prevent duplicate delivery.
    const issue = publishedIssue || await createWeeklyNewsletter(now);
    try {
      const delivery = await sendNewsletterIssue(issue, getPublicAppOrigin(req));
      return res.json({ issueDate: issue.issue_date, websitePublished: true, emailDelivered: true, recoveryRun: local.hour > settings.deliveryHour, ...delivery });
    } catch (deliveryError) {
      console.error('Newsletter published on website but scheduled email delivery failed:', deliveryError instanceof Error ? deliveryError.message : 'Unknown error');
      return res.status(503).json({ issueDate: issue.issue_date, websitePublished: true, emailDelivered: false, error: 'The issue is live on the website; email delivery will retry later today.' });
    }
  } catch (error) {
    console.error('Weekly newsletter job failed:', error instanceof Error ? error.message : 'Unknown error');
    return res.status(500).json({ error: 'Newsletter job failed' });
  }
});

// Authenticated, non-secret SMTP diagnostic. This verifies the connection but
// does not send an email or return credential values.
app.get('/api/email-health', authenticateToken, async (_req: any, res) => {
  const missingVariables = getMissingSmtpVariables();
  if (missingVariables.length > 0) {
    return res.status(503).json({
      status: 'misconfigured',
      configured: false,
      missingVariables,
    });
  }

  try {
    const transporter = await getTransporter();
    if (!transporter) {
      return res.status(503).json({ status: 'misconfigured', configured: false });
    }

    await transporter.verify();
    return res.json({ status: 'ready', configured: true, connection: true });
  } catch (error: any) {
    const smtpError = getSafeSmtpError(error);
    console.error('SMTP health check failed:', smtpError);
    return res.status(502).json({
      status: 'connection_failed',
      configured: true,
      connection: false,
      smtpError,
    });
  }
});

const moveOverdueActivities = async (supabase: any, kidId: string, kid: any, today: string, currentTime: number) => {
  let isPastEndTime = false;
  if (kid.end_time) {
    const [endHour, endMinute] = kid.end_time.split(':').map(Number);
    const endTime = endHour * 60 + endMinute;
    if (currentTime >= endTime) {
      isPastEndTime = true;
    }
  }

  console.log('moveOverdueActivities: kidId:', kidId, 'today:', today, 'currentTime:', currentTime, 'isPastEndTime:', isPastEndTime);

  if (!supabase) {
    console.error('moveOverdueActivities: supabase is undefined');
    return;
  }

  // Find pending activities that are overdue
  // If past end_time, activities due today or earlier are overdue.
  // If not past end_time, only activities due before today are overdue.
  let query = supabase
    .from('activities')
    .select('id, due_date')
    .eq('kid_id', kidId)
    .eq('status', 'pending');

  if (isPastEndTime) {
    query = query.lte('due_date', today);
  } else {
    query = query.lt('due_date', today);
  }

  const { data: overdueActivities, error: overdueError } = await query;
  
  if (overdueError) {
    // Check if it's an HTML error (Cloudflare/Supabase infrastructure)
    const errorMsg = overdueError.message || '';
    if (errorMsg.includes('<!DOCTYPE html>') || errorMsg.includes('<html') || (typeof overdueError === 'string' && overdueError.includes('<html'))) {
      console.warn(`moveOverdueActivities: Supabase/Cloudflare connection issue (5xx error) for kid ${kidId}. Skipping this check.`);
      return;
    }
    console.error('moveOverdueActivities: Error fetching overdue activities:', overdueError);
    // Don't throw for transient infrastructure errors
    return;
  }

  console.log('moveOverdueActivities: overdueActivities:', overdueActivities);

  if (overdueActivities && overdueActivities.length > 0) {
    // Calculate target date
    // If past end_time, move to tomorrow
    // If not past end_time, move to today
    let targetDateStr = today;
    if (isPastEndTime) {
      const baseDate = new Date(today + 'T12:00:00');
      const tomorrow = new Date(baseDate);
      tomorrow.setDate(tomorrow.getDate() + 1);
      targetDateStr = tomorrow.toISOString().split('T')[0];
    }

    console.log(`moveOverdueActivities: Moving ${overdueActivities.length} activities for kid ${kidId} to ${targetDateStr}.`);
    const { error: moveError } = await supabase
      .from('activities')
      .update({ due_date: targetDateStr })
      .in('id', overdueActivities.map((a: any) => a.id));

    if (moveError) {
      // Check if it's an HTML error
      const errorMsg = moveError.message || '';
      if (errorMsg.includes('<!DOCTYPE html>') || errorMsg.includes('<html') || (typeof moveError === 'string' && moveError.includes('<html'))) {
        console.warn(`moveOverdueActivities: Supabase/Cloudflare connection issue (5xx error) during move for kid ${kidId}.`);
        return;
      }
      console.error('moveOverdueActivities: Error updating activities:', moveError);
      return;
    }
  }
};

