app.patch('/api/admin/parents/:userId/admin-role', authenticateToken, requireAppAdmin, async (req: any, res) => {
  const enabled = req.body?.enabled === true;
  const targetUserId = req.params.userId;
  if (!enabled && targetUserId === req.user.id) return res.status(400).json({ error: 'You cannot remove your own administrator access' });
  const admin = getAdminSupabaseClient();
  const result = enabled
    ? await admin.from('app_admins').upsert({ user_id: targetUserId })
    : await admin.from('app_admins').delete().eq('user_id', targetUserId);
  if (result.error) return res.status(500).json({ error: 'Unable to update administrator access' });
  await admin.from('admin_audit_events').insert({ admin_user_id: req.user.id, target_user_id: targetUserId, action: enabled ? 'admin_granted' : 'admin_removed' });
  res.json({ isAdmin: enabled });
});

app.patch('/api/admin/parents/:userId/membership', authenticateToken, requireAppAdmin, async (req: any, res) => {
  const status = req.body?.status === 'active' ? 'active' : req.body?.status === 'cancelled' ? 'cancelled' : null;
  const reason = String(req.body?.reason || '').trim().slice(0, 500);
  if (!status) return res.status(400).json({ error: 'Choose active or cancelled membership' });
  if (status === 'cancelled' && !reason) return res.status(400).json({ error: 'Enter a reason for cancelling membership' });
  if (req.params.userId === req.user.id && status === 'cancelled') return res.status(400).json({ error: 'You cannot cancel your own administrator membership' });
  const admin = getAdminSupabaseClient();
  const { error } = await admin.from('users').update({
    membership_status: status,
    membership_cancelled_at: status === 'cancelled' ? new Date().toISOString() : null,
    membership_cancelled_reason: status === 'cancelled' ? reason : null,
  }).eq('id', req.params.userId);
  if (error) return res.status(500).json({ error: 'Unable to update membership' });
  await admin.from('admin_audit_events').insert({ admin_user_id: req.user.id, target_user_id: req.params.userId, action: status === 'cancelled' ? 'membership_cancelled' : 'membership_reactivated', reason: reason || null });
  res.json({ membershipStatus: status });
});

app.get('/api/admin/traffic', authenticateToken, requireAppAdmin, async (req, res) => {
  const days = Math.min(90, Math.max(7, Number.parseInt(String(req.query.days || '30'), 10) || 30));
  const since = new Date(Date.now() - days * 86400000).toISOString();
  const admin = getAdminSupabaseClient();
  const { data, error } = await admin.from('site_analytics_events').select('visitor_hash,page_path,feature,country_code,region_code,referrer_domain,device_category,visited_at').gte('visited_at', since).order('visited_at', { ascending: true }).limit(10000);
  if (error) return res.status(500).json({ error: 'Unable to load website traffic' });
  const events = data || [];
  const group = (key: string) => {
    const counts = new Map<string, number>();
    events.forEach((row: any) => { const value = String(row[key] || 'Unknown'); counts.set(value, (counts.get(value) || 0) + 1); });
    return [...counts.entries()].map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value).slice(0, 12);
  };
  const dailyMap = new Map<string, { views: number; visitors: Set<string> }>();
  events.forEach((row: any) => { const date = row.visited_at.slice(0, 10); const item = dailyMap.get(date) || { views: 0, visitors: new Set<string>() }; item.views += 1; item.visitors.add(row.visitor_hash); dailyMap.set(date, item); });
  res.json({
    days,
    totals: { views: events.length, visitors: new Set(events.map((row: any) => row.visitor_hash)).size },
    daily: [...dailyMap.entries()].map(([date, item]) => ({ date, views: item.views, visitors: item.visitors.size })),
    countries: group('country_code'), regions: group('region_code'), features: group('feature'), pages: group('page_path'), referrers: group('referrer_domain'), devices: group('device_category'),
  });
});

// Upload File Endpoint
app.post('/api/upload', authenticateToken, (req: any, res) => {
  upload.single('image')(req, res, async (err: any) => {
    if (err) {
      if (err.code === 'LIMIT_FILE_SIZE') {
        return res.status(413).json({ error: 'Image must be 5 MB or smaller' });
      }
      console.error('Upload parser error:', err);
      return res.status(400).json({ error: 'Invalid image upload' });
    }

    if (!req.file) {
      return res.status(400).json({ error: 'Choose a JPEG, PNG, WebP, or GIF image' });
    }

    const detectedType = detectImageType(req.file.buffer);
    if (!detectedType || detectedType !== req.file.mimetype) {
      return res.status(400).json({ error: 'The file content does not match a supported image type' });
    }

    const objectPath = `${req.user.id}/${uuidv4()}.${getImageExtension(detectedType)}`;
    const storageClient = getSupabaseClient(req.token);
    const { error: storageError } = await storageClient.storage
      .from(UPLOAD_BUCKET)
      .upload(objectPath, req.file.buffer, {
        contentType: detectedType,
        cacheControl: '31536000',
        upsert: false,
      });

    if (storageError) {
      console.error('Supabase image upload failed:', storageError.message);
      return res.status(500).json({ error: 'Image storage is unavailable. Please try again.' });
    }

    const { data } = storageClient.storage.from(UPLOAD_BUCKET).getPublicUrl(objectPath);
    return res.status(201).json({ imageUrl: data.publicUrl });
  });
});

// Create Profile
app.post('/api/auth/create-profile', async (req: any, res) => {
  const { id, email, name, privacyAccepted, termsAccepted } = req.body;
  const normalizedEmail = String(email || '').trim().toLowerCase();
  
  if (!id || !normalizedEmail) {
    console.log('create-profile: missing fields');
    return res.status(400).json({ error: 'Missing required fields' });
  }
  if (privacyAccepted !== true || termsAccepted !== true) {
    return res.status(400).json({ error: 'Privacy Policy and Terms acceptance is required' });
  }

  try {
    // Use admin client to bypass RLS during profile creation
    // This is necessary because the user might not have a session yet (e.g. if email confirmation is required)
    // The database foreign key constraint on auth.users(id) ensures only valid users can have profiles.
    const supabaseAdmin = getAdminSupabaseClient();
    const { error } = await supabaseAdmin
      .from('users')
      .insert([
        { 
          id, 
          email: normalizedEmail,
          name, 
          privacy_accepted_at: new Date().toISOString(),
          terms_accepted_at: new Date().toISOString(),
          legal_version: '2026-08-25'
        }
      ]);

    if (error) {
      console.error('Supabase profile creation error:', error);
      if (error.code === '23505') { // Postgres unique constraint violation
        return res.status(409).json({ error: 'Profile already exists' });
      }
      return res.status(500).json({ 
        error: 'Database error during profile creation', 
        details: error.message,
        code: error.code
      });
    }
    
    console.log('Profile created successfully for id:', id);
    
    // The welcome message is intentionally delayed until the address has been
    // confirmed and the parent completes a successful authenticated sign-in.
    res.status(201).json({ message: 'Profile created' });
  } catch (error: any) {
    console.error('Unexpected profile creation error:', error);
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

const sendWelcomeEmailOnce = async (userId: string) => {
  const supabaseAdmin = getAdminSupabaseClient();
  const { data: profile, error: profileError } = await supabaseAdmin
    .from('users')
    .select('email, name, welcome_email_sent_at')
    .eq('id', userId)
    .single();

  if (profileError || !profile) throw new Error('Parent profile not found');
  if (profile.welcome_email_sent_at) return { emailSent: true, alreadySent: true };

  // Reserve delivery before invoking SMTP so simultaneous session/profile
  // refreshes cannot send duplicate welcome messages.
  const reservedAt = new Date().toISOString();
  const { data: reservedRows, error: reserveError } = await supabaseAdmin
    .from('users')
    .update({ welcome_email_sent_at: reservedAt })
    .eq('id', userId)
    .is('welcome_email_sent_at', null)
    .select('id');
  if (reserveError) throw new Error('Welcome email status could not be updated');
  if (!reservedRows?.length) return { emailSent: true, alreadySent: true };

  const emailSent = await sendWelcomeEmail(profile.email, profile.name);
  if (!emailSent) {
    await supabaseAdmin.from('users').update({ welcome_email_sent_at: null }).eq('id', userId).eq('welcome_email_sent_at', reservedAt);
    throw new Error('Welcome email could not be sent');
  }
  return { emailSent: true, alreadySent: false };
};

// Finish registration only after Supabase has verified ownership of the email.
// The authenticated user ID and email come from the verified token, never from
// a client-provided profile ID.
app.post('/api/auth/complete-registration', authenticateToken, async (req: any, res) => {
  try {
    const supabaseAdmin = getAdminSupabaseClient();
    const { data: authResult, error: authError } = await supabaseAdmin.auth.getUser(req.token);
    const authUser = authResult?.user;
    if (authError || !authUser?.id || !authUser.email) {
      return res.status(401).json({ error: 'Your verified session could not be confirmed. Please open the verification link again.' });
    }
    if (!authUser.email_confirmed_at) {
      return res.status(403).json({ error: 'Confirm your email before completing registration.' });
    }

    const metadata = authUser.user_metadata || {};
    if (metadata.privacyAccepted !== true || metadata.termsAccepted !== true) {
      return res.status(400).json({ error: 'Privacy Policy and Terms acceptance was not recorded. Please create the account again.' });
    }

    const normalizedEmail = authUser.email.trim().toLowerCase();
    const safeName = String(metadata.name || normalizedEmail.split('@')[0]).trim().slice(0, 120);
    const acceptedAt = new Date().toISOString();
    const { data: existingProfile, error: existingError } = await supabaseAdmin
      .from('users')
      .select('id')
      .eq('id', authUser.id)
      .maybeSingle();
    if (existingError) throw existingError;

    if (!existingProfile) {
      const { error: insertError } = await supabaseAdmin.from('users').insert({
        id: authUser.id,
        email: normalizedEmail,
        name: safeName,
        privacy_accepted_at: acceptedAt,
        terms_accepted_at: acceptedAt,
        legal_version: String(metadata.legalVersion || '2026-08-25'),
      });
      if (insertError && insertError.code !== '23505') throw insertError;
    }

    const welcomeResult = await sendWelcomeEmailOnce(authUser.id);
    return res.status(existingProfile ? 200 : 201).json({ profileCreated: !existingProfile, ...welcomeResult });
  } catch (error: any) {
    console.error('Verified registration completion error:', error);
    const welcomeFailed = String(error?.message || '').includes('Welcome email');
    return res.status(welcomeFailed ? 502 : 500).json({
      error: welcomeFailed ? 'Your account is verified, but the welcome email could not be sent yet.' : 'Your verified account could not be prepared yet.',
    });
  }
});

