app.post('/api/quiz-results', authenticateToken, async (req: any, res) => {
  const supabase = getSupabaseForUser(req);
  const { quizId, kidId, activityId, responses, score, totalQuestions } = req.body;
  console.log('[POST /api/quiz-results] Request body:', req.body);

  if (!quizId || !kidId || score === undefined || !responses || totalQuestions === undefined) {
    console.error('[POST /api/quiz-results] Missing required fields:', { quizId, kidId, responses, score, totalQuestions });
    return res.status(400).json({ error: 'Missing required fields' });
  }

  if (req.user.role === 'kid' && req.user.kidId !== kidId) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  if (req.user.role === 'kid' && !activityId) {
    return res.status(400).json({ error: 'Assigned quiz context is required' });
  }

  let attemptGeneration: number | null = null;
  if (activityId) {
    const { data: activity, error: activityError } = await supabase
      .from('activities')
      .select('id, kid_id, link, attempt_generation, last_quiz_attempt_generation, kids!inner(user_id)')
      .eq('id', activityId)
      .eq('kid_id', kidId)
      .eq('kids.user_id', req.user.id)
      .single();

    if (activityError || !activity) return res.status(403).json({ error: 'Quiz assignment not found' });
    const linkedQuizId = typeof activity.link === 'string'
      ? activity.link.match(/\/play-quiz\/([^/?#]+)/)?.[1]
      : undefined;
    if (linkedQuizId && decodeURIComponent(linkedQuizId) !== quizId) {
      return res.status(400).json({ error: 'Quiz does not match this assignment' });
    }

    attemptGeneration = Math.max(1, Number(activity.attempt_generation) || 1);
    if (Number(activity.last_quiz_attempt_generation) === attemptGeneration) {
      return res.status(409).json({ error: 'This assigned quiz has already been completed', code: 'QUIZ_ATTEMPT_LOCKED' });
    }
    const { data: existingResult } = await supabase
      .from('quiz_results')
      .select('id')
      .eq('activity_id', activityId)
      .eq('attempt_generation', attemptGeneration)
      .maybeSingle();
    if (existingResult) {
      return res.status(409).json({ error: 'This assigned quiz has already been completed', code: 'QUIZ_ATTEMPT_LOCKED' });
    }
  }

  const { data, error } = await supabase
    .from('quiz_results')
    .insert([{ 
        quiz_id: quizId, 
        kid_id: kidId, 
        activity_id: activityId || null,
        attempt_generation: attemptGeneration,
        responses, 
        score, 
        total_questions: totalQuestions,
        questions: req.body.questions,
        completed_at: new Date().toISOString()
    }]);

  if (error) {
    console.error('[POST /api/quiz-results] Supabase error:', JSON.stringify(error, null, 2));
    if (error.code === '23505') {
      return res.status(409).json({ error: 'This assigned quiz has already been completed', code: 'QUIZ_ATTEMPT_LOCKED' });
    }
    return res.status(500).json({ error: error.message });
  }
  res.status(201).json(data);
});

app.get('/api/quiz-attempts/:activityId', authenticateToken, async (req: any, res) => {
  const supabase = getSupabaseForUser(req);
  const { activityId } = req.params;
  const { data: activity, error: activityError } = await supabase
    .from('activities')
    .select('id, kid_id, attempt_generation, last_quiz_attempt_generation, kids!inner(user_id)')
    .eq('id', activityId)
    .eq('kids.user_id', req.user.id)
    .single();

  if (activityError || !activity || (req.user.role === 'kid' && activity.kid_id !== req.user.kidId)) {
    return res.status(403).json({ error: 'Quiz assignment not found' });
  }

  const attemptGeneration = Math.max(1, Number(activity.attempt_generation) || 1);
  const { data: result, error: resultError } = await supabase
    .from('quiz_results')
    .select('id, score, total_questions, completed_at')
    .eq('activity_id', activityId)
    .eq('attempt_generation', attemptGeneration)
    .maybeSingle();
  if (resultError) return res.status(500).json({ error: 'Unable to check quiz attempt' });

  const submissionRemembered = Number(activity.last_quiz_attempt_generation) === attemptGeneration;
  res.json({ locked: submissionRemembered || Boolean(result), attemptGeneration, result: result || null });
});

app.get('/api/kids/:kidId/quiz-results', authenticateToken, async (req: any, res) => {
  const supabase = getSupabaseForUser(req);
  const { kidId } = req.params;
  const userId = req.user.id;

  try {
    // Verify kid ownership
    const { data: kid, error: kidError } = await supabase
      .from('kids')
      .select('user_id')
      .eq('id', kidId)
      .single();
    
    if (kidError || !kid || kid.user_id !== userId) return res.status(403).json({ error: 'Forbidden' });

    const { data, error } = await supabase
      .from('quiz_results')
      .select('*, quizzes(title)')
      .eq('kid_id', kidId)
      .order('completed_at', { ascending: false });

    if (error) return res.status(500).json({ error: error.message });
    res.json({ results: data });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.delete('/api/kids/:kidId/quiz-results/:quizResultId', authenticateToken, async (req: any, res) => {
  if (req.user.role === 'kid') return res.status(403).json({ error: 'Parent access required' });

  const supabase = getSupabaseForUser(req);
  const { kidId, quizResultId } = req.params;

  try {
    const { data: kid, error: kidError } = await supabase
      .from('kids')
      .select('id')
      .eq('id', kidId)
      .eq('user_id', req.user.id)
      .maybeSingle();

    if (kidError || !kid) return res.status(403).json({ error: 'Forbidden' });

    const { data: existingResult, error: resultError } = await supabase
      .from('quiz_results')
      .select('id')
      .eq('id', quizResultId)
      .eq('kid_id', kidId)
      .maybeSingle();

    if (resultError) return res.status(500).json({ error: 'Unable to check quiz result' });
    if (!existingResult) return res.status(404).json({ error: 'Quiz result not found' });

    const { data: deletedResult, error: deleteError } = await supabase
      .from('quiz_results')
      .delete()
      .eq('id', quizResultId)
      .eq('kid_id', kidId)
      .select('id')
      .maybeSingle();

    if (deleteError) return res.status(500).json({ error: 'Unable to delete quiz result' });
    if (!deletedResult) return res.status(403).json({ error: 'Quiz-result deletion is not enabled yet. Apply the latest quiz-result retention migration and try again.' });

    res.json({ success: true, deletedId: deletedResult.id });
  } catch (error) {
    console.error('Quiz result deletion failed:', error);
    res.status(500).json({ error: 'Unable to delete quiz result' });
  }
});

app.get('/api/data-management', authenticateToken, async (req: any, res) => {
  if (req.user.role === 'kid') return res.status(403).json({ error: 'Parent access required' });
  const supabase = getSupabaseForUser(req);

  try {
    const { data: profile, error: profileError } = await supabase
      .from('users')
      .select('data_review_months, last_data_review_at')
      .eq('id', req.user.id)
      .single();
    if (profileError) return res.status(500).json({ error: 'Unable to load data-management settings' });

    const reviewMonths = Math.max(3, Math.min(36, Number(profile?.data_review_months) || 12));
    const cutoff = new Date();
    cutoff.setUTCMonth(cutoff.getUTCMonth() - reviewMonths);
    const cutoffIso = cutoff.toISOString();

    const { data: kids, error: kidsError } = await supabase.from('kids').select('id, name').eq('user_id', req.user.id);
    if (kidsError) return res.status(500).json({ error: 'Unable to load family data' });
    const kidIds = (kids || []).map(kid => kid.id);
    const empty = Promise.resolve({ count: 0, data: [], error: null } as any);
    const count = (table: string, byKid = false) => {
      if (byKid && kidIds.length === 0) return empty;
      let query: any = supabase.from(table).select('id', { count: 'exact', head: true });
      query = byKid ? query.in('kid_id', kidIds) : query.eq('user_id', req.user.id);
      return query;
    };

    const [activities, history, quizResults, quizzes, worksheets, stories, purchases, messages, bonuses] = await Promise.all([
      count('activities', true), count('activity_history', true), count('quiz_results', true), count('quizzes'),
      count('worksheets'), count('social_stories'), count('reward_purchases', true), count('parent_messages'), count('behavior_bonus_awards', true),
    ]);

    const oldQuizPromise = kidIds.length ? supabase.from('quiz_results').select('id, kid_id, completed_at, quizzes(title)').in('kid_id', kidIds).lt('completed_at', cutoffIso).order('completed_at', { ascending: true }).limit(100) : empty;
    const oldHistoryPromise = kidIds.length ? supabase.from('activity_history').select('id, kid_id, activity_type, description, completion_date, created_at').in('kid_id', kidIds).lt('created_at', cutoffIso).order('created_at', { ascending: true }).limit(100) : empty;
    const oldPurchasePromise = kidIds.length ? supabase.from('reward_purchases').select('id, kid_id, item_name, purchased_at').in('kid_id', kidIds).lt('purchased_at', cutoffIso).order('purchased_at', { ascending: true }).limit(100) : empty;
    const [oldQuiz, oldHistory, oldPurchases] = await Promise.all([oldQuizPromise, oldHistoryPromise, oldPurchasePromise]);
    const kidNames = new Map((kids || []).map(kid => [kid.id, kid.name]));

    res.json({
      settings: { reviewMonths, lastReviewedAt: profile?.last_data_review_at || null, cutoff: cutoffIso },
      counts: {
        children: kidIds.length, activities: activities.count || 0, activityHistory: history.count || 0,
        quizResults: quizResults.count || 0, savedQuizzes: quizzes.count || 0, worksheets: worksheets.count || 0,
        socialStories: stories.count || 0, rewardPurchases: purchases.count || 0, parentMessages: messages.count || 0,
        behaviorBonuses: bonuses.count || 0,
      },
      reviewItems: [
        ...(oldQuiz.data || []).map((item: any) => ({ id: item.id, type: 'quiz_result', title: item.quizzes?.title || 'Quiz result', date: item.completed_at, learner: kidNames.get(item.kid_id) || 'Learner' })),
        ...(oldHistory.data || []).map((item: any) => ({ id: item.id, type: 'activity_history', title: item.activity_type || item.description || 'Activity history', date: item.completion_date || item.created_at, learner: kidNames.get(item.kid_id) || 'Learner' })),
        ...(oldPurchases.data || []).map((item: any) => ({ id: item.id, type: 'reward_purchase', title: item.item_name || 'Reward purchase', date: item.purchased_at, learner: kidNames.get(item.kid_id) || 'Learner' })),
      ].sort((a, b) => new Date(a.date || 0).getTime() - new Date(b.date || 0).getTime()),
    });
  } catch (error) {
    console.error('Data management summary failed:', error);
    res.status(500).json({ error: 'Unable to load data-management summary' });
  }
});

app.put('/api/data-management/settings', authenticateToken, async (req: any, res) => {
  if (req.user.role === 'kid') return res.status(403).json({ error: 'Parent access required' });
  const reviewMonths = Number(req.body?.reviewMonths);
  if (!Number.isInteger(reviewMonths) || reviewMonths < 3 || reviewMonths > 36) return res.status(400).json({ error: 'Review period must be between 3 and 36 months' });
  const supabase = getSupabaseForUser(req);
  const { error } = await supabase.from('users').update({ data_review_months: reviewMonths, last_data_review_at: new Date().toISOString() }).eq('id', req.user.id);
  if (error) return res.status(500).json({ error: 'Unable to save review settings' });
  res.json({ success: true, reviewMonths });
});

app.delete('/api/data-management/records', authenticateToken, async (req: any, res) => {
  if (req.user.role === 'kid') return res.status(403).json({ error: 'Parent access required' });
  const records = Array.isArray(req.body?.records) ? req.body.records : [];
  if (!records.length) return res.status(400).json({ error: 'Select at least one record' });
  if (records.length > 300) return res.status(400).json({ error: 'Select no more than 300 records at a time' });
  const allowedTables: Record<string, string> = { quiz_result: 'quiz_results', activity_history: 'activity_history', reward_purchase: 'reward_purchases' };
  if (records.some((record: any) => !allowedTables[record.type] || typeof record.id !== 'string')) return res.status(400).json({ error: 'Invalid cleanup selection' });

  const supabase = getSupabaseForUser(req);
  const { data: kids } = await supabase.from('kids').select('id').eq('user_id', req.user.id);
  const kidIds = (kids || []).map(kid => kid.id);
  if (!kidIds.length) return res.status(403).json({ error: 'Forbidden' });

  let deleted = 0;
  for (const [type, table] of Object.entries(allowedTables)) {
    const ids = records.filter((record: any) => record.type === type).map((record: any) => record.id);
    if (!ids.length) continue;
    const { data, error } = await supabase.from(table).delete().in('id', ids).in('kid_id', kidIds).select('id');
    if (error) return res.status(500).json({ error: 'Unable to delete selected records' });
    deleted += data?.length || 0;
  }
  await supabase.from('users').update({ last_data_review_at: new Date().toISOString() }).eq('id', req.user.id);
  res.json({ success: true, deleted });
});

// Kid Management Routes
app.post('/api/kids', authenticateToken, async (req: any, res) => {
  const supabase = getSupabaseForUser(req);
  const { 
    name, 
    dob, 
    grade_level: gradeLevel, 
    hobbies, 
    interests, 
    strengths, 
    weaknesses, 
    sensory_issues: sensoryIssues, 
    behavioral_issues: behavioralIssues, 
    avatar, 
    start_time: startTime, 
    end_time: endTime, 
    max_incomplete_limit: maxIncompleteLimit, 
    reward_type: rewardType, 
    reward_quantity: rewardQuantity, 
    bonus_history_limit: bonusHistoryLimit,
    optional_bonus_daily_reward_limit: optionalBonusDailyRewardLimit,
    rules, 
    theme, 
    can_print: canPrint, 
    timezone, 
    kid_code: kidCode,
    therapies
  } = req.body;
  const userId = req.user.id;

  if (!name) return res.status(400).json({ error: 'Name is required' });

  try {
    const id = uuidv4();
    const maxLimit = maxIncompleteLimit && !isNaN(parseInt(maxIncompleteLimit, 10)) ? parseInt(maxIncompleteLimit, 10) : null;
    const rewardQty = rewardQuantity && !isNaN(parseInt(rewardQuantity, 10)) ? parseInt(rewardQuantity, 10) : 1;
    const parsedBonusHistoryLimit = Number.parseInt(String(bonusHistoryLimit), 10);
    const bonusHistoryLimitValue = Number.isFinite(parsedBonusHistoryLimit) ? Math.min(10, Math.max(1, parsedBonusHistoryLimit)) : 5;
    const parsedOptionalRewardLimit = Number.parseInt(String(optionalBonusDailyRewardLimit), 10);
    const optionalRewardLimitValue = Number.isFinite(parsedOptionalRewardLimit)
      ? Math.min(100, Math.max(1, parsedOptionalRewardLimit))
      : 10;
    const start_time = startTime && startTime !== '' ? startTime : null;
    const end_time = endTime && endTime !== '' ? endTime : null;
    
    const dataToInsert: any = {
      id,
      user_id: userId,
      name,
      dob,
      grade_level: gradeLevel,
      hobbies,
      interests,
      strengths,
      weaknesses,
      sensory_issues: sensoryIssues,
      behavioral_issues: behavioralIssues,
      can_print: canPrint,
      avatar,
      start_time: start_time,
      end_time: end_time,
      max_incomplete_limit: maxLimit,
      reward_type: rewardType || 'Penny',
      reward_quantity: rewardQty,
      bonus_history_limit: bonusHistoryLimitValue,
      optional_bonus_daily_reward_limit: optionalRewardLimitValue,
      rules,
      theme: theme || 'sky',
      kid_code: kidCode,
      reward_balance: 0,
      therapies,
      timezone
    };

    console.log('API: Inserting kid:', JSON.stringify(dataToInsert));
    const { error } = await supabase
      .from('kids')
      .insert([dataToInsert]);

    if (error) {
      console.error('API: Supabase kid insert error:', {
        message: error.message,
        details: error.details,
        hint: error.hint,
        code: error.code
      });
      if (error.code === '42703' || error.code === 'PGRST204') {
        // Fallback: try kidcode instead of kid_code, and remove potentially missing columns
        const { 
          timezone: _tz, 
          start_time: _st, 
          end_time: _et, 
          kid_code: _kc, 
          reward_balance: _rb,
          therapies: _th,
          can_print: _cp,
          max_incomplete_limit: _mil,
          reward_type: _rt,
          reward_quantity: _rq,
          sensory_issues: _si,
          behavioral_issues: _bi,
          grade_level: _gl,
          ...fallbackData 
        } = dataToInsert;
        
        const dataWithOldCode: any = { ...fallbackData };
        if (_kc !== undefined) dataWithOldCode.kidcode = _kc;
        if (_gl !== undefined) dataWithOldCode.gradelevel = _gl; // Another common variation
        
        console.log('API: Attempting fallback insert with data:', JSON.stringify(dataWithOldCode));
        const { error: retryError } = await supabase.from('kids').insert([dataWithOldCode]);
        
        if (retryError && (retryError.code === '42703' || retryError.code === 'PGRST204')) {
          // If it still fails, try a VERY minimal insert
          console.log('API: Fallback insert failed, attempting final minimal insert');
          const minimalData = {
            id,
            user_id: userId,
            name,
            avatar: avatar || null
          };
          console.log('API: Final minimal insert data:', JSON.stringify(minimalData));
          const { error: finalError } = await supabase.from('kids').insert([minimalData]);
          
          if (finalError && (finalError.code === '42703' || finalError.code === 'PGRST204')) {
             // Last ditch effort: maybe it's parent_id instead of user_id
             console.log('API: Minimal insert failed, trying parent_id fallback');
             const lastDitchData = {
               id,
               parent_id: userId,
               name,
               avatar: avatar || null
             };
             const { error: lastDitchError } = await supabase.from('kids').insert([lastDitchData]);
             if (lastDitchError) throw lastDitchError;
          } else if (finalError) {
            throw finalError;
          }
        } else if (retryError) {
          throw retryError;
        }
      } else {
        throw error;
      }
    }


    const io = req.app.get('io');
    if (io) io.to(`kid_${id}`).emit('data_updated', { kidId: id });

    res.status(201).json({ message: 'Kid added successfully', kid: { id, name } });
  } catch (error: any) {
    console.error('Create kid error:', JSON.stringify(error, Object.getOwnPropertyNames(error)));
    res.status(500).json({ 
      error: 'Internal server error',
      message: error.message || 'No message',
      details: error.details || 'No details',
      hint: error.hint || 'No hint',
      code: error.code || 'No code',
      debug: 'v2'
    });
  }
});


